import * as THREE from 'three/webgpu';
import { texture, uv, vec4 } from 'three/tsl';
import gsap from 'gsap';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-journal-card-1-label';
  group.position.set(0, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const width = 1.6;
  const height = 1.0;

  const geometry = new THREE.PlaneGeometry(width, height);
  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  const map = ctx.textureLoader.load('/prism-mock/home/nodes/feature-card.png');
  map.colorSpace = THREE.SRGBColorSpace;

  const uvNode = uv();
  material.colorNode = texture(map, uvNode);
  material.opacityNode = vec4(1, 1, 1, 1).a;

  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'card-plane';
  group.add(plane);

  const textMesh = createTextMesh({
    text: 'Journal 2',
    font: 'Lora',
    weight: 400,
    sizeEm: 0.34,
    color: config.colors?.paper || '#e8ecf2',
    atlas: ctx.fontAtlas,
    maxWidth: width * 0.85
  });
  textMesh.position.set(0, 0, 0.01);
  group.add(textMesh);

  // Cinematic primitive: parallax-scroll
  ctx.primitives['parallax-scroll'](group, { intensity: 0.25 });

  // Interaction state
  const basePosition = group.position.clone();
  let hoverTween = null;
  let pressTween = null;

  function onPointerOver() {
    if (pressTween) pressTween.kill();
    hoverTween = gsap.to(group.position, {
      y: basePosition.y + 0.15,
      duration: 0.7,
      ease: 'power3.out'
    });
  }

  function onPointerOut() {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(group.position, {
      y: basePosition.y,
      duration: 0.7,
      ease: 'power3.out'
    });
  }

  function onClick() {
    if (hoverTween) hoverTween.kill();
    pressTween = gsap.timeline()
      .to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' })
      .to(group.scale, { x: 1, y: 1, z: 1, duration: 0.3, ease: 'back.out' });

    if (group.userData.emit) {
      group.userData.emit('hub-journal.select', { id: 'hub-journal-card-1' });
    }
  }

  group.userData.handlers = {
    onPointerOver,
    onPointerOut,
    onClick
  };

  group.userData.emit = (eventName, payload) => {
    if (ctx.eventBus && typeof ctx.eventBus.emit === 'function') {
      ctx.eventBus.emit(eventName, payload);
    }
  };

  group.userData.cleanup = () => {
    if (hoverTween) hoverTween.kill();
    if (pressTween) pressTween.kill();
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
    if (textMesh.userData && typeof textMesh.userData.cleanup === 'function') {
      textMesh.userData.cleanup();
    }
    if (group.userData.parallaxCleanup) {
      group.userData.parallaxCleanup();
    }
  };

  return group;
}
